-- KLI English institutional proficiency preparation form (two-section publishable practice).
-- It follows TOEFL ITP Level 1 section timing for Structure and Reading but is not an ETS test or score equivalent.
create table if not exists public.assessment_stimuli(id uuid primary key default gen_random_uuid(),code text not null unique,title text not null,content text not null,stimulus_type text not null check(stimulus_type in ('reading','listening_script')),created_at timestamptz not null default now());
alter table public.assessment_stimuli enable row level security;
create policy stimuli_public_read on public.assessment_stimuli for select using(true);
create policy stimuli_staff_manage on public.assessment_stimuli for all using(public.current_role() in ('academic','admin','superadmin')) with check(public.current_role() in ('academic','admin','superadmin'));
alter table public.assessment_questions add column if not exists stimulus_id uuid references public.assessment_stimuli(id) on delete set null;
values('EN-ITP-SR-DIAGNOSTIC','English','TOEFL ITP Level 1 preparation','Intermediate–Advanced','certification_readiness','KLI Structure & Reading Proficiency Diagnostic','A 90-item KLI-original preparation diagnostic covering Structure and Written Expression (40) plus Reading Comprehension (50). Not an official ETS test or score equivalent.',80,70,true,'1.0','academic_review','practice','content_ready',3,24)
on conflict(code) do update set title=excluded.title,description=excluded.description,duration_minutes=excluded.duration_minutes,published=true,usage_scope='practice';
select id,'TOEFL ITP Level 1 section counts and timing; KLI-original content','Commercial preparation practice and formative diagnostic only','Intermediate to advanced English learners','{"structure_written_expression":40,"reading_comprehension":50}'::jsonb,90,false,'70% provisional practice threshold; no ETS score conversion' from public.assessment_tests where code='EN-ITP-SR-DIAGNOSTIC'
on conflict(test_id) do update set standard_reference=excluded.standard_reference,intended_use=excluded.intended_use,skills=excluded.skills,min_objective_items=90,requires_human_rating=false;
select id,'structure','Structure and Written Expression','structure_written_expression',25,40,'["sentence_completion","error_identification"]'::jsonb,1,'TOEFL ITP Level 1 preparation structure; KLI-original items' from public.assessment_tests where code='EN-ITP-SR-DIAGNOSTIC' on conflict(test_id,code) do update set duration_minutes=25,target_item_count=40;
select id,'reading','Reading Comprehension','reading_comprehension',55,50,'["main_idea","detail","inference","vocabulary","reference","rhetorical_function","organization"]'::jsonb,2,'TOEFL ITP Level 1 preparation structure; KLI-original passages and items' from public.assessment_tests where code='EN-ITP-SR-DIAGNOSTIC' on conflict(test_id,code) do update set duration_minutes=55,target_item_count=50;
delete from public.assessment_questions where test_id=(select id from public.assessment_tests where code='EN-ITP-SR-DIAGNOSTIC');

comment on table public.assessment_stimuli is 'KLI-owned assessment passages/scripts. Public practice release does not imply psychometric validation.';